async function getMetadata() {
        if (normalized.kind === 'character') {
            return safeInvoke('get_character_chat_metadata', {
                characterName: normalized.characterId,
                fileName: normalized.fileName,
            });
        }

        return safeInvoke('get_group_chat_metadata', { chatId: normalized.chatId });
    }

export async function saveChatConditional(commitReason = CHAT_COMMIT_REASON.MUTATION) {
    // A full save includes all pending chat and metadata edits; later edits schedule new saves.
    cancelDebouncedChatSave();
    cancelDebouncedMetadataSave();

    const savePromise = selected_group
        ? saveGroupChat(selected_group, true, false, commitReason)
        : saveChat({ commitReason });

    // Keep prompt/token persistence serialized with chat writes to avoid
    // chat switches corrupting per-chat IndexedDB state.
    const chatId = getCurrentChatId();
    const tokenCacheSaveState = captureTokenCacheSaveState(chatId);
    const itemizedPromptsSnapshot = captureItemizedPromptsSaveSnapshot(chatId);
    const postSavePromise = enqueueChatSave(async () => {
        await saveTokenCache(tokenCacheSaveState);
        await saveItemizedPrompts(chatId, {
            entriesSnapshot: itemizedPromptsSnapshot,
            cloneFromActive: false,
        });
    });

    await Promise.all([savePromise, postSavePromise]);
}

pub async fn get_character_chat_metadata(
    character_name: String,
    file_name: String,
    app_state: State<'_, Arc<AppState>>,
) -> Result<Value, CommandError> {
    log_command(format!(
        "get_character_chat_metadata {}/{}",
        character_name, file_name
    ));

    app_state
        .services
        .chat_service
        .get_character_chat_metadata(&character_name, &file_name)
        .await
        .map_err(map_command_error(format!(
            "Failed to get chat metadata {}/{}",
            character_name, file_name
        )))
}

pub(super) async fn read_optional_chat_metadata_from_path(
        &self,
        path: &Path,
    ) -> Result<Option<Value>, DomainError> {
        let Some(header) = read_header_bytes(path).await? else {
            return Ok(None);
        };
        Ok(parse_header(&header)
            .map_err(|error| header_error(path, error))?
            .remove("chat_metadata"))
    }
